uint8_t *X86_get_op_access(cs_struct *h, unsigned int id, uint64_t *eflags)
{
        unsigned int i = find_insn(insns, ARR_SIZE(insns), id);
        if (i != -1) {
                *eflags = insn_ops[i].flags;
                return insn_ops[i].access;
        }

        return NULL;
}

void X86_reg_access(const cs_insn *insn,
                cs_regs regs_read, uint8_t *regs_read_count,
                cs_regs regs_write, uint8_t *regs_write_count)
{
        uint8_t i;
        uint8_t read_count, write_count;
        cs_x86 *x86 = &(insn->detail->x86);

        read_count = insn->detail->regs_read_count;
        write_count = insn->detail->regs_write_count;

        // implicit registers
        memcpy(regs_read, insn->detail->regs_read, read_count * sizeof(insn->detail->regs_read[0]));
        memcpy(regs_write, insn->detail->regs_write, write_count * sizeof(insn->detail->regs_write[0]));

        // explicit registers
        for (i = 0; i < x86->op_count; i++) {
                cs_x86_op *op = &(x86->operands[i]);
                switch((int)op->type) {
                        case X86_OP_REG:
                                if ((op->access & CS_AC_READ) && !arr_exist(regs_read, read_count, op->reg)) {
                                        regs_read[read_count] = op->reg;
                                        read_count++;
                                }
                                if ((op->access & CS_AC_WRITE) && !arr_exist(regs_write, write_count, op->reg)) {
                                        regs_write[write_count] = op->reg;
                                        write_count++;
                                }
                                break;
                        case X86_OP_MEM:
                                // registers appeared in memory references always being read
                                if ((op->mem.segment != X86_REG_INVALID)) {
                                        regs_read[read_count] = op->mem.segment;
